create table if not exists regime_states(id text primary key, regime text not null, confidence integer not null default 0, features jsonb not null default '{}'::jsonb, evidence_scope text not null default 'live', observed_at timestamptz not null default now());
create table if not exists model_ensemble_scores(id text primary key, opportunity_id text not null references opportunities(id), security_id text not null references securities(id), regime text not null, champion_model text, challenger_model text, champion_score numeric(12,6), challenger_score numeric(12,6), disagreement numeric(12,6), decision_score numeric(12,6), evidence jsonb not null default '{}'::jsonb, shadow_only boolean not null default true, computed_at timestamptz not null default now());
create table if not exists portfolio_decisions(id text primary key, security_id text references securities(id), opportunity_id text references opportunities(id), regime text, target_weight numeric(12,8) not null default 0, max_weight numeric(12,8) not null default 0, marginal_risk numeric(12,8), liquidity_capacity numeric(18,4), cluster_key text, decision text not null, reasons jsonb not null default '[]'::jsonb, shadow_only boolean not null default true, capital_execution_enabled boolean not null default false, observed_at timestamptz not null default now());
create table if not exists replay_evidence(id text primary key, experiment_id text references research_experiments(id), model_version text, regime text, dataset_hash text not null, point_in_time boolean not null default true, walk_forward boolean not null default false, leakage_passed boolean not null default false, transaction_costs_included boolean not null default false, metrics jsonb not null default '{}'::jsonb, created_at timestamptz not null default now());
create table if not exists economic_proof_gates(id text primary key, model_version text, evidence_scope text not null default 'live', sample_size integer not null default 0, regimes integer not null default 0, net_expectancy numeric(18,8), max_drawdown numeric(18,8), rolling_stability numeric(18,8), capacity_score numeric(18,8), stress_survival numeric(18,8), ex_top_winners_expectancy numeric(18,8), synthetic_rows integer not null default 0, passed boolean not null default false, reasons jsonb not null default '[]'::jsonb, evaluated_at timestamptz not null default now());
create table if not exists paper_orders(id text primary key, security_id text not null references securities(id), opportunity_id text references opportunities(id), side text not null, requested_qty numeric(24,6) not null, filled_qty numeric(24,6) not null default 0, requested_price numeric(18,8), average_fill_price numeric(18,8), status text not null default 'simulated', latency_ms integer, slippage_bps numeric(12,4), reject_reason text, simulation jsonb not null default '{}'::jsonb, capital_execution_enabled boolean not null default false, created_at timestamptz not null default now());
do $$ declare r record; begin for r in select tablename from pg_tables where schemaname='public' and tablename in ('regime_states','model_ensemble_scores','portfolio_decisions','replay_evidence','economic_proof_gates','paper_orders') loop execute format('alter table public.%I enable row level security',r.tablename); execute format('revoke all on table public.%I from anon, authenticated',r.tablename); end loop; end $$;